UPDATE VISUALIZATIONS SET "TYPE"=8, CAPTION='Resultado Domiciliación', DESCRIPTION='Domiciliación Dólares', "STATEMENT"='SELECT ''EGRESOS'' "Tipo de Transaccion", ''CDKEVI1'' "Cod. Cajero", ''SAN PEDRO DE MONTES DE OCA'' "Oficina Comercial", OP.RECEIPT "Transaccion", OP.ISSUEDATE "Fecha", 
       ''CT Cobro'' "Oper.", B.CARD "Ref Doc.", NULL "Cheque", NULL "Cta. Simp", ''COBROS DE RECIBOS'' "Descripcion", OP.POLICYID "Poliza", OP.FIRSTNAME || '' '' || OP.LASTNAME "Tercero", 
       OP.AMOUNT * A500.VAL_CAMBIO "Importe Local Mon", A500.VAL_CAMBIO "Val. Cambio", OP.AMOUNT "Importe Ext.", OP.BILLNUMBER "Num. Recibo", a700.NUM_AVISO "Num. Aviso"
  FROM ALIADOS.ONLINEPAYMENT OP
  JOIN ALIADOS.BOVEDA B ON DECODE(B.TIP_DOCUM, ''CNA'', 1, ''CRE'', 2, ''PAS'', 3, ''CJU'', 4, NULL)=OP.DOCUMENTTYPE AND B.COD_DOCUM=OP.DOCUMENTNUMBER AND  B.NUM_POLIZA=OP.POLICYID
  JOIN A2990700 a700 ON a700.NUM_RECIBO  = OP.BILLNUMBER
  JOIN A1000500 A500 ON A500.COD_MON=OP.CURRENCY AND A500.FEC_CAMBIO = (SELECT MAX(FEC_CAMBIO) FROM A1000500 WHERE COD_MON=OP.CURRENCY)  
 WHERE OP.PROVIDERSTATUS =''APPROVED'' AND OP.Source=''Recurring'' AND OP.CURRENCY=2 AND OP.ProcessId={processId:varchar}', ICON=NULL, ICONCLASS=NULL, VALUEFORMAT=NULL, ENTITYTYPE=NULL, RECORDSTATUS=1, COMPANYID=1, UPDATEUSERCODE=111, UPDATEDATE=TIMESTAMP '2025-05-20 00:00:00.000000', SPECIFICATION=NULL, CONNECTIONNAME='tron', STATEMENTTYPE=1, DIALOG=NULL, STATEMENTEXTEND=NULL, "KEY"='ReporteDomiciliacion', JAVASCRIPTTOINCLUDE=NULL WHERE ID=110 AND "SEQUENCE"=2;